 JSONArray baseRows=new JSONArray(),topicRows=new JSONArray(),sourceRows=new JSONArray(),historyRows=new JSONArray();final List<CheckBox>sourceChecks=new ArrayList<>();String heldTopic="",expectedState="",draftSha="",baselineSha="",fullText="",exportText="",exportName="产业主题完整阅读.txt",readingKey="archive";int mode,segment,historyPage;long epoch;boolean active,filling,dark;BiConsumer<String,String> exportRequested;
