 JSONObject config()throws Exception{JSONArray list=new JSONArray();for(String line:urls.getText().toString().split("\\R"))if(!line.trim().isEmpty())list.put(line.trim());JSONObject c=object("enabled",enabled.isChecked(),"intervalMinutes",Integer.parseInt(interval.getText().toString().trim()),"sourceIds",selectedSources(),"sourceUrls",list,"proposals",new JSONArray(proposals.getText().toString()),"useAi",false);new WatchlistBackupModel.JsonGate(proposals.getText().toString()).run();IndustryTopicStore.config(c);return c;}
