 void renderHistory()throws Exception{historyBody.removeAllViews();int count=Math.max(1,(historyRows.length()+49)/50);LinearLayout nav=new LinearLayout(getContext());historyBody.addView(nav);button(nav,"上一页","f08HistoryPrevious",()->{historyPage=Math.max(0,historyPage-1);renderHistory();});button(nav,"下一页","f08HistoryNext",()->{historyPage=Math.min(Math.max(0,(historyRows.length()-1)/50),historyPage+1);renderHistory();});label(historyBody,"第 "+(historyPage+1)+" / "+count+" 页，共 "+historyRows.length()+" 条完整记录");for(int n=historyPage*50;n<Math.min(historyRows.length(),historyPage*50+50);n++){JSONObject r=historyRows.getJSONObject(historyRows.length()-1-n);String key=r.getString("key");LinearLayout line=new LinearLayout(getContext());historyBody.addView(line);button(line,r.getString("label"),"f08HistoryRow",()->open(key));}if(historyRows.length()==0)label(historyBody,"尚无本主题执行/版本记录。");theme(historyBody);}
 void open(String key)throws Exception{JSONObject snapshot=store.snapshot();fullText=IndustryTopicView.read(snapshot,key);exportText=key.equals("archive")?snapshot.getString("archive"):key.equals("original")?snapshot.getString("originalArchive"):fullText;exportName=key.equals("archive")||key.equals("original")?"产业主题完整档案.json":"产业主题完整阅读.txt";readingKey=key;segment=0;showMode(2);renderReading();}
 void showMode(int value){mode=value;epoch++;controls.setVisibility(value==2?GONE:VISIBLE);readerControls.setVisibility(value==2?VISIBLE:GONE);configScroll.setVisibility(value==0?VISIBLE:GONE);historyScroll.setVisibility(value==1?VISIBLE:GONE);readScroll.setVisibility(value==2?VISIBLE:GONE);}
