 JSONObject draftValue()throws Exception{return object("schema","native-industry-update-draft/v1","baseline",baseRows.length()==0?"":selected(baseRows,baselines),"topic",topicRows.length()==0?"":topic(),"sourceIds",selectedSources(),"sourceUrls",urls.getText().toString(),"proposals",proposals.getText().toString(),"enabled",enabled.isChecked(),"interval",interval.getText().toString(),"mode",mode,"readingKey",readingKey,"segment",segment);}
