 void restore(JSONObject d)throws Exception{IndustryTopicDraft.check(d);filling=true;try{choices(baselines,baseRows,d.getString("baseline"));choices(topics,topicRows,d.getString("topic"));urls.setText(d.getString("sourceUrls"));proposals.setText(d.getString("proposals"));interval.setText(d.getString("interval"));enabled.setChecked(d.getBoolean("enabled"));Set<String>ids=new HashSet<>();JSONArray a=d.getJSONArray("sourceIds");for(int i=0;i<a.length();i++)ids.add(a.getString(i));applySources(ids);ack.setChecked(false);baselineSha="";readingKey=d.getString("readingKey");segment=d.getInt("segment");mode=d.getInt("mode");heldTopic=d.getString("topic");if(mode==2){if(readingKey.startsWith("baseline:"))fullText=IndustryTopicSources.baseline(rows.get(),readingKey.substring(9));else fullText=IndustryTopicView.read(store.snapshot(),readingKey);exportText=readingKey.equals("archive")?store.snapshot().getString("archive"):readingKey.equals("original")?store.snapshot().getString("originalArchive"):fullText;exportName=readingKey.equals("archive")||readingKey.equals("original")||readingKey.startsWith("baseline:")?"产业主题完整档案.json":"产业主题完整阅读.txt";renderReading();}}finally{filling=false;}showMode(mode);}
 void setActive(boolean value){if(active==value)return;if(!value){runtime.cancelManual();epoch++;safe(this::saveDraft);}active=value;if(value){ack.setChecked(false);baselineSha="";}}
 int background(){return dark?android.graphics.Color.rgb(17,25,38):android.graphics.Color.WHITE;}
