 void theme(View view){if(view instanceof TextView)((TextView)view).setTextColor(ink());if(view instanceof EditText)((EditText)view).setHintTextColor(dark?0xff99a8bc:0xff64748b);if(view instanceof Button&&!(view instanceof CheckBox))view.setBackgroundTintList(android.content.res.ColorStateList.valueOf(dark?0xff29394e:0xffe8eef6));if(view instanceof CheckBox)((CheckBox)view).setButtonTintList(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{0xff3883d1,dark?0xffa0aec0:0xff64748b}));if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int n=0;n<group.getChildCount();n++)theme(group.getChildAt(n));}}
